export function handleListed(event: Listed): void {
  let id = event.params.nft.toHex() + "-" +
           event.params.tokenId.toString();
  let listing = new Listing(id);
  listing.seller = event.params.seller;
  listing.price = event.params.price;
  listing.active = true;
  listing.save();
}

